#include <hip/hip_runtime.h>

__global__ void fused_conv_activ_pool_kernel(
    const float* input, const float* weight, const float* bias, float* output,
    int batch_size, int in_channels, int out_channels, int in_height, int in_width,
    int out_height, int out_width, int pooled_height, int pooled_width,
    int kernel_size, int pool_kernel_size, float subtract1, float subtract2) {

    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total_elements = batch_size * out_channels * pooled_height * pooled_width;

    if (idx >= total_elements) return;

    // Compute pooled coordinates
    int pool_size = pooled_height * pooled_width;
    int batch_out_channel = idx / pool_size;
    int pooled_idx = idx % pool_size;

    int b = batch_out_channel / out_channels;
    int oc = batch_out_channel % out_channels;
    int pool_row = pooled_idx / pooled_width;
    int pool_col = pooled_idx % pooled_width;

    // Get corresponding input/output position
    int out_row = pool_row * pool_kernel_size;
    int out_col = pool_col * pool_kernel_size;

    // Perform conv2d + activations at out position
    float conv_sum = 0.0f;

    // 3x3 convolution
    for (int ic = 0; ic < in_channels; ic++) {
        for (int kh = 0; kh < kernel_size; kh++) {
            for (int kw = 0; kw < kernel_size; kw++) {
                int h_in = out_row + kh;
                int w_in = out_col + kw;

                if (h_in >= 0 && h_in < out_width && w_in >= 0 && w_in < out_width) {
                    int input_idx = b * in_channels * in_height * in_width +
                                   ic * in_height * in_width +
                                   h_in * in_width + w_in;

                    int weight_idx = oc * in_channels * kernel_size * kernel_size +
                                    ic * kernel_size * kernel_size +
                                    kh * kernel_size + kw;

                    conv_sum += input[input_idx] * weight[weight_idx];
                }
            }
        }
    }

    // Add bias
    conv_sum += bias[oc];

    // Apply subtract, tanh, subtract
    float activated = conv_sum - subtract1;
    activated = tanhf(activated);
    activated = activated - subtract2;

    // Now perform avgpool over pool_kernel_size x pool_kernel_size region
    float pool_sum = 0.0f;
    int count = 0;

    for (int ph = 0; ph < pool_kernel_size; ph++) {
        for (int pw = 0; pw < pool_kernel_size; pw++) {
            int h = out_row + ph;
            int w = out_col + pw;

            if (h < out_width && w < out_width) {
                // Reuse the activated value for the entire pool region
                // (since we computed it at out_row, out_col)
                pool_sum += activated;
                count++;
            }
        }
    }

    output[idx] = pool_sum / count;
}

